package com.mps.operations; import com.mps.auth.security.UserPrincipal; import com.mps.common.ApiResponse; import com.mps.operations.dto.OperationsDtos.*; import com.mps.operations.service.OperationsService; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1/operations") @PreAuthorize("hasAnyRole('SUPER_ADMIN','ORG_ADMIN')") public class OperationsController {private final OperationsService service;public OperationsController(OperationsService s){service=s;}@GetMapping("/health") public ApiResponse<HealthView> health(){return ApiResponse.ok("Operational health loaded.",service.health());}@GetMapping("/backups") public ApiResponse<List<BackupView>> backups(@AuthenticationPrincipal UserPrincipal p){return ApiResponse.ok("Backup jobs loaded.",service.backups(p));}@PostMapping("/backups") public ApiResponse<BackupView> backup(@AuthenticationPrincipal UserPrincipal p,@RequestParam(defaultValue="FULL")String type){return ApiResponse.ok("Backup request queued.",service.requestBackup(p,type));}@GetMapping("/alerts") public ApiResponse<List<AlertView>> alerts(){return ApiResponse.ok("Operational alerts loaded.",service.alerts());}@PostMapping("/alerts/{id}/acknowledge") public ApiResponse<AlertView> acknowledge(@AuthenticationPrincipal UserPrincipal p,@PathVariable UUID id){return ApiResponse.ok("Alert acknowledged.",service.acknowledge(p,id));}}
